function normalizeUrl(value) {
  return String(value).trim().replace(/[\\/,]+$/, '');
}

function requireEnvironment() {
  const required = [
    'SUPABASE_URL',
    'SUPABASE_ANON_KEY',
    'CLIENT_EMAIL',
    'CLIENT_PASSWORD',
    'DRIVER_EMAIL',
    'DRIVER_PASSWORD',
  ];
  const missing = required.filter((name) => !__ENV[name]);
  if (missing.length) throw new Error(`Faltan variables requeridas: ${missing.join(', ')}`);
}

function login(role, email, password) {
  const response = http.post(
    `${SUPABASE_URL}/auth/v1/token?grant_type=password`,
    JSON.stringify({ email, password }),
    {
      headers: {
        apikey: __ENV.SUPABASE_ANON_KEY,
        Authorization: `Bearer ${__ENV.SUPABASE_ANON_KEY}`,
        'Content-Type': 'application/json',
      },
      responseType: 'text',
      tags: { kind: 'auth', role, endpoint: 'supabase_login' },
      timeout: SETUP_REQUEST_TIMEOUT,
    },
  );
  if (response.status !== 200) {
    throw new Error(`No se pudo autenticar el rol ${role}. HTTP ${response.status}.`);
  }
  const token = response.json('access_token');
  if (!token) throw new Error(`Supabase no devolvió access_token para ${role}.`);
  return token;
}

function authHeaders(token) {
  return { Authorization: `Bearer ${token}`, Accept: 'application/json' };
}

function validateRole(role, path, token) {
  const response = http.get(`${BASE_URL}${path}`, {
    headers: authHeaders(token),
    tags: { kind: 'validation', role, endpoint: 'role_validation' },
    timeout: SETUP_REQUEST_TIMEOUT,
  });
  if (response.status !== 200) {
    throw new Error(`La validación del rol ${role} falló en ${path}. HTTP ${response.status}.`);
  }
}

export function setup() {
  requireEnvironment();
  let health;
  for (let attempt = 1; attempt <= SETUP_MAX_ATTEMPTS; attempt += 1) {
    health = http.get(`${BASE_URL}/`, {
      tags: { kind: 'validation', role: 'public', endpoint: 'health' },
      timeout: SETUP_REQUEST_TIMEOUT,
    });
    if (health.status === 200) break;
    const detail = health.error ? ` (${health.error})` : '';
    console.warn(`Prevalidación ${attempt}/${SETUP_MAX_ATTEMPTS}: HTTP ${health.status}${detail}.`);
    if (attempt < SETUP_MAX_ATTEMPTS) sleep(SETUP_RETRY_DELAY_SECONDS);
  }
  if (!health || health.status !== 200) {
    const detail = health?.error ? ` (${health.error})` : '';
    throw new Error(
      `El backend no superó la prevalidación tras ${SETUP_MAX_ATTEMPTS} intentos. ` +
      `HTTP ${health?.status || 0}${detail}. La prueba de rendimiento no llegó a ejecutarse.`,
    );
  }

  const clientToken = login('client', __ENV.CLIENT_EMAIL, __ENV.CLIENT_PASSWORD);
  const driverToken = login('driver', __ENV.DRIVER_EMAIL, __ENV.DRIVER_PASSWORD);
  validateRole('client', '/api/solicitudes/mis-pedidos', clientToken);
  validateRole('driver', '/api/transportista/dashboard', driverToken);
  return { clientToken, driverToken };
}

function endpointForIteration(iteration) {
  // 37 es coprimo con 100: dispersa las primeras iteraciones por toda la
  // distribución ponderada y evita que un smoke corto pruebe solo el inicio.
  const bucket = (iteration * 37) % 100;
  let upperBound = 0;
  for (const endpoint of endpoints) {
    upperBound += endpoint.weight;
    if (bucket < upperBound) return endpoint;
  }
  return endpoints[endpoints.length - 1];
}

function requestUrl(endpoint) {
  if (endpoint.key === 'buscar_localidades') {
    return `${BASE_URL}${endpoint.path}?q=${encodeURIComponent(__ENV.SEARCH_QUERY || 'Cordoba')}`;
  }
  return `${BASE_URL}${endpoint.path}`;
}

function tokenFor(endpoint, data) {
  if (endpoint.role === 'client') return data.clientToken;
  if (endpoint.role === 'driver') return data.driverToken;
  return null;
}

export function runFlow(data) {
  const profileId = execution.scenario.name;
  const endpoint = endpointForIteration(execution.scenario.iterationInTest);
  const token = tokenFor(endpoint, data);
  const tags = { kind: 'api', profile: profileId, endpoint: endpoint.key, role: endpoint.role };
  const response = http.get(requestUrl(endpoint), {
    headers: token ? authHeaders(token) : { Accept: 'application/json' },
    tags,
    timeout: REQUEST_TIMEOUT,
  });

  const successful = response.status === 200;
  const timedOut = String(response.error || '').toLowerCase().includes('timeout');
  check(response, { [`${endpoint.key} responde HTTP 200`]: () => successful }, tags);

  const profileMetrics = metrics[profileId];
  const endpointMetrics = profileMetrics.endpoints[endpoint.key];
  profileMetrics.duration.add(response.timings.duration);
  profileMetrics.success.add(successful);
  profileMetrics.errors.add(!successful);
  profileMetrics.timeouts.add(timedOut);
  endpointMetrics.duration.add(response.timings.duration);
  endpointMetrics.success.add(successful);
  endpointMetrics.errors.add(!successful);
  endpointMetrics.timeouts.add(timedOut);

  sleep(THINK_TIME_SECONDS);
}

export function handleSummary(data) {
  const evaluation = evaluateSummary(data, PROFILE, { runId: RUN_ID, baseUrl: BASE_URL });
  const baseName = `${RUN_ID}-${PROFILE}`;
  const paths = {
    json: `performance/results/${baseName}-summary.json`,
    markdown: `performance/reports/${baseName}-report.md`,
    html: `performance/reports/${baseName}-report.html`,
  };
  return {
    [paths.json]: JSON.stringify({ evaluation, k6: data }, null, 2),
    [paths.markdown]: renderMarkdown(evaluation),
    [paths.html]: renderHtml(evaluation),
    stdout: renderConsole(evaluation, paths),
  };
}
